                    $username=$eventXML.Event.EventData.Data[0]."#text"
                    $securityid=$eventXML.Event.EventData.Data[1]."#text"
                    switch ($event.id){
                        4728 {$output += "  User added to global $groupname group`n"}
                        4732 {$output += "  User added to local $groupname group`n"}
