                    $output+= "  Unsigned image:`r`n"
                    $output+= $pscommand
                 }
             }
        }
        if ($output){
            $event.TimeCreated 
            $output
            ""
        }
    }
    if ($failedlogons -gt $maxfailedlogons){
         "High number of failed logons in the security event log: " + $failedlogons 
