          }
        2 {
              #########
              ## CMD ##
              #########

              # Undo some escaping from beginning of function.
              ForEach($Char in $CharsToEscape)
              {
                  If($ScriptString.Contains("^^^$Char")) {$ScriptString = $ScriptString.Replace("^^^$Char",$Char)}
